SELECT report.id, report.create_time date, report.quantity, report.process_id, report.team_id, user.`name` user_name, leader.`name` leaderName, factory.`name` 'factory.name', workshop.`name` 'workshop.name', production_line.`name` 'production_line.name', process.`name` process_name FROM mes_building_produce_team_report report LEFT JOIN mes_building_task_process task_process ON report.task_process_id=task_process.id LEFT JOIN mes_building_factory factory ON factory.id=task_process.factory_id LEFT JOIN mes_building_workshop workshop ON workshop.id=task_process.workshop_id LEFT JOIN mes_building_production_line production_line ON production_line.id=task_process.production_line_id LEFT JOIN mes_building_process process ON process.id=report.process_id LEFT JOIN sys_user user ON user.id=report.user_id LEFT JOIN mes_building_team_user_link team_user_link ON team_user_link.team_id=report.team_id AND team_user_link.bool_delete_enum=FALSE AND team_user_link.bool_leader_enum=TRUE LEFT JOIN sys_user leader ON leader.id=team_user_link.user_id
report.bool_delete_enum=FALSE AND report.product_id=#{id} AND report.product_type=#{prodcutType}
