SELECT DISTINCT report.process_id 'process.id', process.`name` 'process.name', production_line.id 'productionLine.id', production_line.`name` 'productionLine.name', users.id 'user.id', users.`name` 'user.name', tulink.user_name 'team.name', sum(report.quantity) quantity, process.sort ,report.create_time date FROM mes_building_produce_team_report report LEFT JOIN mes_building_task_process task_process ON report.task_process_id = task_process.id and task_process.bool_delete_enum = FALSE LEFT JOIN mes_building_production_line production_line ON production_line.id = task_process.production_line_id and production_line.bool_delete_enum = FALSE LEFT JOIN mes_building_process process ON process.id = report.process_id and process.bool_delete_enum = FALSE LEFT JOIN sys_user users ON users.id = report.user_id and users.bool_delete_enum = FALSE LEFT JOIN mes_building_team_user_link tulink on report.team_id = tulink.team_id and tulink.bool_delete_enum=FALSE and tulink.bool_leader_enum = 1 WHERE report.bool_delete_enum = FALSE AND report.product_id = #{productId}
AND report.task_type_enum=#{taskTypeEnum}
AND report.number=#{number}
GROUP BY report.process_id, production_line.id, tulink.user_name, users.id, report.create_time

select.if:
SELECT `month`, SUM( mete ) mete FROM ( SELECT DATE_FORMAT( complete.create_time, "%Y-%m" ) `month`, complete.quantity * artifact.net_weight mete FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id WHERE complete.task_type_enum = 2
AND complete.project_id = #{projectId}
AND DATE_FORMAT(complete.create_time, "%Y" ) = DATE_FORMAT(#{dateTime}, "%Y")
) a GROUP BY `month`

SELECT `month` as dateTime, SUM( mete ) mete FROM ( SELECT DATE_FORMAT( complete.create_time, "%Y-%m" ) `month`, complete.quantity * artifact.net_weight mete FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE complete.task_type_enum = 2
AND DATE_FORMAT(complete.create_time, "%Y" ) = DATE_FORMAT(#{dateTime}, "%Y")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = cp.id )
AND complete.workshop_id = #{workshopId}
) a GROUP BY `month`

mapper.select:
SELECT process.id 'process.id', process.`name` 'process.name', process.product_type task_type_enum, workshop.id 'workshop.id', workshop.`name` 'workshop.name', line.id 'prodLine.id', line.`name` 'prodLine.name', a.team_id 'team.id', user_link.user_name 'team.name', a.inspection_quantity, a.net_weight, a.gross_weight, CASE process.product_type WHEN 1 THEN 1 WHEN 2 THEN 3 WHEN 16 THEN 2 END task_type_enum_sort, process.sort FROM ( SELECT report.process_id, report.production_line_id, report.team_id, IFNULL( SUM( report.inspection_quantity ), 0 ) inspection_quantity, CASE report.task_type_enum WHEN 1 THEN IFNULL( SUM( report.inspection_quantity * part.net_weight ), 0 ) WHEN 2 THEN IFNULL( SUM( report.inspection_quantity * artifact.net_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( report.inspection_quantity * assemble.net_weight ), 0 ) END net_weight, CASE report.task_type_enum WHEN 1 THEN IFNULL( SUM( report.inspection_quantity * part.gross_weight ), 0 ) WHEN 2 THEN IFNULL( SUM( report.inspection_quantity * artifact.gross_weight ), 0 ) WHEN 16 THEN IFNULL( SUM( report.inspection_quantity * assemble.net_weight ), 0 ) END gross_weight FROM `mes_building_produce_team_report` report LEFT JOIN mes_building_task task on report.task_id = task.id LEFT JOIN tech_artifact artifact ON artifact.id = report.product_id LEFT JOIN tech_assemble assemble ON assemble.id = report.product_id LEFT JOIN tech_machine_part part ON part.id = report.product_id WHERE report.bool_delete_enum = 0
AND task.project_id=#{projectId}
AND report.process_id=#{processId}
AND report.in_year_month_day_date >= date_format(#{startDate}, '%Y-%m-%d')
AND report.in_year_month_day_date <= date_format(#{endDate}, '%Y-%m-%d')
AND task.project_id=#{projectId}
GROUP BY report.team_id, report.process_id, report.production_line_id, report.task_type_enum ) a LEFT JOIN mes_building_process process ON process.id = a.process_id LEFT JOIN mes_building_production_line line ON line.id = a.production_line_id LEFT JOIN mes_building_workshop workshop ON workshop.id = line.workshop_id LEFT JOIN mes_building_team_user_link user_link ON user_link.team_id = a.team_id AND user_link.bool_delete_enum = 0 AND user_link.bool_leader_enum = 1 WHERE a.inspection_quantity > 0
AND workshop.id=#{workshopId}
ORDER BY task_type_enum_sort ASC , process.sort ASC

