ORDER BY report.create_time DESC,report.team_id ASC

SELECT report.productId 'productId' , report.reprotQuantity 'reprotQuantity' , report.inspectionQuantity 'inspectionQuantity', report.report_time 'reportTime', report.report_number 'reportNumberId', report.task_process_id 'taskProcessId', report.task_type_enum, report.team_id 'team.id', report.user_id, pro.id 'project.id', pro.`name` 'project.name', pro.short_name 'project.short_name', pro.serial_number 'project.serial_number', mon.id 'monomer.id', mon.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', user.id 'user.id', user.name 'user.name', mba.serial_number 'serialNumber', task.bool_one_code 'booleOneCode', workshop.id 'workshop.id', workshop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', bgroups.id 'groups.id', bgroups.name 'groups.name' FROM ( SELECT a.task_id, a.task_process_id, a.product_id productId, a.groups_id, a.task_type_enum, a.team_id, a.user_id, a.report_time, a.report_number, SUM( a.quantity ) reprotQuantity, SUM( a.inspection_quantity + problem_quantity ) inspectionQuantity FROM mes_building_produce_team_report a WHERE a.bool_delete_enum = FALSE and a.inspection_quantity + problem_quantity=0
AND date(a.report_time) >=date(#{startDate})
AND date(a.report_time) < date(#{endDate})
AND a.task_id = #{taskId}
AND a.task_process_id =#{taskProcessId}
AND a.process_id = #{processId}
AND a.product_id = #{productId}
AND a.task_type_enum &#{taskTypeEnum}
AND a.groups_id = #{groupId}
and a.team_id in
#{teamId}
GROUP BY a.task_id, a.task_process_id, a.product_id, a.groups_id, a.task_type_enum, a.team_id, a.user_id, a.report_time, a.report_number ) report LEFT JOIN mes_building_task_process process ON report.task_process_id = process.id AND process.bool_delete_enum = 0 LEFT JOIN mes_building_task task ON report.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN contract_project pro ON process.project_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN plan_monomer mon ON mon.id = process.monomer_id AND mon.bool_delete_enum = 0 LEFT JOIN plan_area area ON process.area_id = area.id AND area.bool_delete_enum = 0
LEFT JOIN tech_machine_part mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_artifact mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_enclosure mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_assemble mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN mes_building_factory factory ON factory.id = process.factory_id LEFT JOIN mes_building_workshop workshop ON workshop.id = process.workshop_id LEFT JOIN mes_building_production_line line ON line.id = process.production_line_id LEFT JOIN mes_building_groups bgroups ON bgroups.id = report.groups_id LEFT JOIN sys_user user ON user.id = report.user_id where 1=1
AND mba.serial_number like CONCAT('%',#{serialNumber},'%')
AND pro.id = #{projectId}
AND mon.id = #{monomerId}
AND area.id = #{areaId}
AND mbw.id = #{workshopId}
AND mbpl.id = #{productLineId}
AND mbf.id = #{factoryId}
order by report.report_number asc

SELECT report.productId 'productId' , report.reprotQuantity 'reprotQuantity' , report.inspectionQuantity 'inspectionQuantity', report.report_time 'reportTime', report.report_number 'reportNumberId', report.task_process_id 'taskProcessId', report.task_type_enum, report.team_id 'team.id', report.report_type, report.user_id, pro.id 'project.id', pro.`name` 'project.name', pro.short_name 'project.short_name', pro.serial_number 'project.serial_number', mon.id 'monomer.id', mon.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', batch.`id` 'areaBatch.id', batch.`name` 'areaBatch.name', user.id 'user.id', user.name 'user.name', mba.serial_number 'serialNumber', task.bool_one_code 'booleOneCode', workshop.id 'workshop.id', workshop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name' FROM ( SELECT a.task_id, a.task_process_id, a.product_id productId, a.task_type_enum, a.team_id, a.user_id, a.report_time, a.report_number, a.report_type, a.workshop_id, a.production_line_id, SUM( a.quantity ) reprotQuantity, SUM( a.inspection_quantity + a.problem_quantity ) inspectionQuantity FROM mes_building_produce_team_report a LEFT JOIN mes_building_task_process process ON a.task_process_id = process.id WHERE a.bool_delete_enum = FALSE and a.inspection_quantity + a.problem_quantity=0
AND date(a.report_time) >=date(#{startDate})
