AND a.task_process_id =#{taskProcessId}
AND a.process_id = #{processId}
AND a.product_id = #{productId}
AND a.task_type_enum &#{taskTypeEnum}
and a.team_id in
#{teamId}
GROUP BY a.task_id, a.task_process_id, a.product_id, a.task_type_enum, a.team_id, a.user_id, a.report_time, a.report_number, a.report_type, a.workshop_id, a.production_line_id ) report LEFT JOIN mes_building_task_process process ON report.task_process_id = process.id AND process.bool_delete_enum = 0 LEFT JOIN mes_building_task task ON report.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN contract_project pro ON process.project_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN plan_monomer mon ON mon.id = process.monomer_id AND mon.bool_delete_enum = 0 LEFT JOIN plan_area area ON process.area_id = area.id AND area.bool_delete_enum = 0 LEFT JOIN plan_area_batch batch ON process.area_batch_id = batch.id AND batch.bool_delete_enum = 0
LEFT JOIN tech_machine_part mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_artifact mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_enclosure mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_assemble mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN mes_building_workshop workshop ON workshop.id = report.workshop_id LEFT JOIN mes_building_production_line line ON line.id = report.production_line_id LEFT JOIN sys_user user ON user.id = report.user_id where 1=1
AND mba.serial_number like CONCAT('%',#{serialNumber},'%')
AND pro.id = #{projectId}
AND mon.id = #{monomerId}
AND area.id = #{areaId}
AND batch.id = #{areaBatchId}
AND workshop.id = #{workshopId}
AND line.id = #{productLineId}
AND workshop.factory_id = #{factoryId}
order by report.report_number asc

SELECT report.productId 'productId' , report.reprotQuantity 'reprotQuantity' , report.inspectionQuantity 'inspectionQuantity', report.report_time 'reportTime', report.task_process_id 'taskProcessId', report.task_type_enum, report.team_id 'team.id', report.user_id, pro.id 'project.id', pro.`name` 'project.name', pro.short_name 'project.short_name', pro.serial_number 'project.serial_number', mon.id 'monomer.id', mon.`name` 'monomer.name', area.id 'area.id', area.`name` 'area.name', user.id 'user.id', user.name 'user.name', mba.serial_number 'serialNumber', task.bool_one_code 'booleOneCode', workshop.id 'workshop.id', workshop.`name` 'workshop.name', line.id 'productionLine.id', line.`name` 'productionLine.name', bgroups.id 'groups.id', bgroups.name 'groups.name' FROM ( SELECT a.task_id, a.task_process_id, a.product_id productId, a.groups_id, a.task_type_enum, a.team_id, a.user_id, a.report_time, SUM( a.quantity ) reprotQuantity, SUM( a.inspection_quantity ) inspectionQuantity FROM mes_building_produce_team_report a WHERE a.bool_delete_enum = FALSE AND a.task_type_enum = 2
AND date(a.report_time) >=date(#{startDate})
AND date(a.report_time) < date(#{endDate})
AND a.task_id = #{taskId}
AND a.task_process_id =#{taskProcessId}
AND a.process_id = #{processId}
