GROUP BY a.task_id, a.task_process_id, a.product_id, a.groups_id, a.task_type_enum, a.team_id, a.user_id, a.report_time ) report LEFT JOIN mes_building_task_process process ON report.task_process_id = process.id AND process.bool_delete_enum = 0 LEFT JOIN mes_building_task task ON report.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN contract_project pro ON process.project_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN plan_monomer mon ON mon.id = process.monomer_id AND mon.bool_delete_enum = 0 LEFT JOIN plan_area area ON process.area_id = area.id AND area.bool_delete_enum = 0
LEFT JOIN tech_machine_part mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_artifact mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_enclosure mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN tech_assemble mba ON report.productId =mba.id AND mba.bool_delete_enum=FALSE
LEFT JOIN mes_building_factory factory ON factory.id = process.factory_id LEFT JOIN mes_building_workshop workshop ON workshop.id = process.workshop_id LEFT JOIN mes_building_production_line line ON line.id = process.production_line_id LEFT JOIN mes_building_groups bgroups ON bgroups.id = report.groups_id LEFT JOIN sys_user user ON user.id = report.user_id where 1=1
mba.serial_number like CONCAT('%',#{serialNumber},'%')
AND pro.id = #{projectId}
