SELECT * FROM mes_building_produce_team_report WHERE
( product_id= #{numberInfo.productId} and number=#{numberInfo.number})
and bool_delete_enum = 0 and task_type_enum=#{taskType}

select IFNULL(SUM(report.inspection_quantity),0)
from mes_building_produce_team_report report
         left join mes_building_team_user_link link on link.team_id = report.team_id
where report.process_id = #{processId}
  and link.user_id = #{userId}
  and DATE_FORMAT(report.create_time, '%Y') =  #{year}

select IFNULL(SUM(report.inspection_quantity),0)
from mes_building_produce_team_report report
         left join mes_building_team_user_link link on link.team_id = report.team_id
where report.process_id = #{processId}
  and link.user_id = #{userId}
  and YEAR(report.create_time) = YEAR(CURDATE() - INTERVAL 1 MONTH)
  AND MONTH(report.create_time) = MONTH(CURDATE() - INTERVAL 1 MONTH);

select link.artifact_id 'productId', link.artifact_number 'number', link.artifact_task_id 'taskId', process.process_id 'processId', wr.status 'status', b.name 'name' from mes_building_task_number_link link LEFT JOIN tech_artifact art on link.artifact_id = art.id LEFT JOIN mes_building_warehouse_record wr on link.artifact_id = wr.product_id and link.artifact_number = wr.number and wr.type = 1 and wr.product_type = #{taskType} and wr.bool_delete_enum = 0 LEFT JOIN mes_building_task_process process on link.artifact_task_process_id = process.id LEFT JOIN mes_building_process b on b.id = process.process_id where link.bool_delete_enum=0 and
( link.artifact_task_id= #{dto.taskId} and link.artifact_id=#{dto.productId})
and art.area_id = #{areaId}
and art.project_id = #{projectId}
and art.monomer_id = #{monomerId}

SELECT shop.`name` shopName, line.id lineId, line.`name` lineName, IFNULL( sum( report.quantity * art.net_weight ), 0)/1000 avgNetWeight FROM mes_building_produce_team_report report LEFT JOIN mes_building_task task ON report.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON task.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN mes_building_workshop shop ON task.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line ON task.production_line_id = line.id AND line.bool_delete_enum = 0 where report.bool_delete_enum = 0 AND report.task_type_enum = 2 and YEAR(report.create_time) = YEAR(CURDATE())
and task.workshop_id = #{workshopId}
GROUP BY shop.`name`, line.id, line.`name`

SELECT shop.`name` shopName, line.`name` lineName, sum(( pro.need_quantity - pro.inspection_quantity ) * art.net_weight )/1000 unTotalNetWeight FROM mes_building_task_process pro Inner JOIN tech_artifact art ON pro.product_id = art.id AND art.bool_delete_enum = 0 and pro.task_type_enum = 2 LEFT JOIN mes_building_workshop shop ON pro.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line ON pro.production_line_id = line.id and line.product_type = 2 AND line.bool_delete_enum = 0 WHERE pro.bool_delete_enum = 0 AND pro.need_quantity - pro.complete_quantity > 0
and pro.workshop_id = #{workshopId}
GROUP BY shop.`name`, line.`name`

SELECT rep.team_id, pro.id processId, pro.`name` processName, tulink.user_name teamLeaderName, CASE rep.task_type_enum WHEN 2 THEN ROUND( IFNULL( sum( rep.quantity * art.net_weight ), 0 )/ 1000, 2 ) ELSE ROUND( IFNULL( sum( rep.quantity * ass.net_weight ), 0 )/ 1000, 2 ) END netWeightSum FROM mes_building_produce_team_report rep LEFT JOIN tech_artifact art ON rep.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN tech_assemble ass ON rep.product_id = ass.id AND ass.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line on rep.production_line_id = line.id and line.bool_delete_enum = 0 LEFT JOIN mes_building_process pro ON rep.process_id = pro.id AND pro.bool_delete_enum = 0 LEFT JOIN mes_building_team_user_link tulink ON rep.team_id = tulink.team_id AND tulink.bool_delete_enum = 0 AND tulink.bool_leader_enum = 1 where rep.bool_delete_enum = 0
AND line.workshop_id = #{workshopId}
and rep.project_id=#{projectId}
AND DATE(rep.create_time)>=DATE(#{startDate})
AND DATE(rep.create_time)<=DATE(#{endDate})
GROUP BY rep.team_id, pro.id, rep.task_type_enum, tulink.user_name

SELECT cp.serial_number proejectSerialNumber, cp.short_name shortName, pm.id monomer.id, pm.name monomer.name, pa.id area.id, pa.name area.name, mba.serial_number serialNumber, mba.specification specification mba.length length, mba.material material, mba.quantity quantity, mba.net_weight netWeight, ROUND( IFNULL( sum( rep.quantity * mba.net_weight ), 0 )/ 1000, 2 ), DATE_FORMAT(rep.create_time,'%Y-%d') FROM mes_building_produce_team_report rep
LEFT JOIN tech_artifact mba ON rep.product_id =mba.id and rep.task_type_enum = 2
LEFT JOIN tech_assemble mba ON rep.product_id =mba.id and rep.task_type_enum = 16
left join contract_project cp on mba.project_id = cp.id and cp.bool_delete_enum = 0 left join plan_monomer pm on mba.monomer_id = pm.id and monomer.bool_delete_enum = 0 left join plan_area pa on mba.area_id = pa.id and pa.bool_delete_enum = 0 where rep.bool_delete_enum = 0 and mba.bool_delete_enum = 0
AND line.workshop_id = #{workshopId}
and rep.project_id=#{projectId}
and pm.id=#{monomerId}
and pa.id=#{areaId}
and rep.team_id = #{teamId}
and rep.process_id = #{processId}
AND DATE(rep.create_time)>=DATE(#{startDate})
AND DATE(rep.create_time)<=DATE(#{endDate})
group by cp.id,pm.id,pa.id,mba.id,DATE_FORMAT(rep.create_time,'%Y-%d')

SELECT rep.process_id, rep.production_line_id, line.name productionLineName, rep.team_id, tulink.user_name teamLeaderName, CASE rep.task_type_enum WHEN 1 THEN ROUND( IFNULL( sum( rep.quantity * part.net_weight ), 0 )/ 1000, 2 ) WHEN 2 THEN ROUND( IFNULL( sum( rep.quantity * art.net_weight ), 0 )/ 1000, 2 ) WHEN 16 THEN ROUND( IFNULL( sum( rep.quantity * ass.net_weight ), 0 )/ 1000, 2 ) ELSE 0 END netWeightSum FROM mes_building_produce_team_report rep LEFT JOIN tech_machine_part part ON rep.product_id = part.id AND part.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON rep.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN tech_assemble ass ON rep.product_id = ass.id AND ass.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line on rep.production_line_id = line.id and line.bool_delete_enum = 0 LEFT JOIN mes_building_team_user_link tulink ON rep.team_id = tulink.team_id AND tulink.bool_delete_enum = 0 AND tulink.bool_leader_enum = 1 where rep.bool_delete_enum = 0
AND line.workshop_id = #{workshopId}
and rep.project_id=#{projectId}
AND DATE(rep.create_time)>=DATE(#{startDate})
AND DATE(rep.create_time)<=DATE(#{endDate})
GROUP BY rep.process_id, rep.production_line_id, rep.team_id, tulink.user_name, task_type_enum

SELECT cp.serial_number proejectSerialNumber, cp.short_name shortName, pm.id 'monomer.id', pm.name 'monomer.name', pa.id 'area.id', pa.name 'area.name', mba.serial_number serialNumber, mba.specification specification, mba.length length, mba.material material, mba.quantity quantity, mba.net_weight netWeight, ROUND( IFNULL( sum( rep.quantity * mba.net_weight ), 0 )/ 1000, 2 ) as totalNetWeight, DATE_FORMAT(rep.create_time,'%Y-%m-%d') as createDate FROM mes_building_produce_team_report rep
LEFT JOIN tech_artifact mba ON rep.product_id =mba.id and rep.task_type_enum = 2
LEFT JOIN tech_assemble mba ON rep.product_id =mba.id and rep.task_type_enum = 16
left join contract_project cp on mba.project_id = cp.id and cp.bool_delete_enum = 0 left join plan_monomer pm on mba.monomer_id = pm.id and pm.bool_delete_enum = 0 left join plan_area pa on mba.area_id = pa.id and pa.bool_delete_enum = 0 where rep.bool_delete_enum = 0 and mba.bool_delete_enum = 0
AND line.workshop_id = #{workshopId}
and rep.project_id=#{projectId}
and pm.id=#{monomerId}
and pa.id=#{areaId}
and rep.team_id = #{teamId}
and rep.process_id = #{processId}
AND DATE(rep.create_time)>=DATE(#{startDate})
AND DATE(rep.create_time)<=DATE(#{endDate})
group by cp.id,pm.id,pa.id,mba.id,DATE_FORMAT(rep.create_time,'%Y-%m-%d')

SELECT DISTINCT report.process_id 'process.id', process.`name` 'process.name', production_line.id 'productionLine.id', production_line.`name` 'productionLine.name', users.id 'user.id', users.`name` 'user.name', tulink.user_name 'team.name', sum(report.inspection_quantity) quantity, process.sort
,report.create_time date
FROM mes_building_produce_inspection_team_report report LEFT JOIN mes_building_task_process task_process ON report.task_process_id = task_process.id LEFT JOIN mes_building_production_line production_line ON production_line.id = task_process.production_line_id LEFT JOIN mes_building_process process ON process.id = report.process_id LEFT JOIN sys_user users ON users.id = report.user_id LEFT JOIN mes_building_team_user_link tulink on report.team_id = tulink.team_id and tulink.bool_delete_enum=FALSE and tulink.bool_leader_enum = 1 WHERE report.bool_delete_enum = FALSE AND report.product_id = #{productId} AND report.task_type_enum = #{taskTypeEnum}
AND report.number=#{number}
GROUP BY report.process_id, production_line.id, tulink.user_name, users.id
,report.create_time

SELECT tulink.user_name teamName, process.name AS processName, ROUND( ( IFNULL(SUM(CASE WHEN tr.task_type_enum = 2 THEN tr.inspection_quantity * art.net_weight ELSE 0 END),0) + IFNULL(SUM(CASE WHEN tr.task_type_enum = 16 THEN tr.inspection_quantity * ass.net_weight ELSE 0 END),0) ) / 1000.0, 2 ) AS totalWeight,
ROUND( ( IFNULL(SUM(CASE WHEN tr.create_time >= DATE_FORMAT(NOW(), '%Y-%m-01') AND tr.create_time < DATE_FORMAT(LAST_DAY(NOW()) + INTERVAL 1 DAY, '%Y-%m-01') AND tr.task_type_enum = 2 THEN tr.inspection_quantity * art.net_weight ELSE 0 END),0) + IFNULL(SUM(CASE WHEN tr.create_time >= DATE_FORMAT(NOW(), '%Y-%m-01') AND tr.create_time < DATE_FORMAT(LAST_DAY(NOW()) + INTERVAL 1 DAY, '%Y-%m-01') AND tr.task_type_enum = 16 THEN tr.inspection_quantity * ass.net_weight ELSE 0 END),0) ) / 1000.0, 2 ) AS currentMonthWeight,
ROUND( ( IFNULL(SUM(CASE WHEN tr.create_time >= DATE_FORMAT(DATE_SUB(NOW(),INTERVAL 1 MONTH),'%Y-%m-01') AND tr.create_time < DATE_FORMAT(NOW(),'%Y-%m-01') AND tr.task_type_enum = 2 THEN tr.inspection_quantity * art.net_weight ELSE 0 END),0) + IFNULL(SUM(CASE WHEN tr.create_time >= DATE_FORMAT(DATE_SUB(NOW(),INTERVAL 1 MONTH),'%Y-%m-01') AND tr.create_time < DATE_FORMAT(NOW(),'%Y-%m-01') AND tr.task_type_enum = 16 THEN tr.inspection_quantity * ass.net_weight ELSE 0 END),0) ) / 1000.0, 2 ) AS lastMonthWeight, ROUND( ( IFNULL(SUM(CASE WHEN tr.create_time >= CURDATE() AND tr.create_time < CURDATE() + INTERVAL 1 DAY AND tr.task_type_enum = 2 THEN tr.inspection_quantity * art.net_weight ELSE 0 END),0) + IFNULL(SUM(CASE WHEN tr.create_time >= CURDATE() AND tr.create_time < CURDATE() + INTERVAL 1 DAY AND tr.task_type_enum = 16 THEN tr.inspection_quantity * ass.net_weight ELSE 0 END),0) ) / 1000.0, 2 ) AS todayWeight FROM mes_building_produce_team_report tr LEFT JOIN mes_building_team_user_link tulink ON tr.team_id = tulink.team_id AND tulink.bool_delete_enum = 0 AND tulink.bool_leader_enum = 1 LEFT JOIN mes_building_task task ON tr.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN mes_building_process process ON process.id = tr.process_id AND process.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON tr.product_id = art.id AND tr.task_type_enum = 2 AND art.bool_delete_enum = 0 LEFT JOIN tech_assemble ass ON tr.product_id = ass.id AND tr.task_type_enum = 16 AND ass.bool_delete_enum = 0 WHERE tr.bool_delete_enum = 0 AND tr.inspection_quantity != 0 AND tr.task_type_enum IN ( 2, 16 )
AND tr.create_time >= CONCAT(#{year},'-01-01') AND tr.create_time < CONCAT(#{year}+1,'-01-01')
AND task.workshop_id = #{workShopId}
AND tr.production_line_id = #{productionId}
GROUP BY tulink.user_name, process.name;

SELECT cp.`name` 'projectName', pss.`name` 'processName', tulink.user_name 'teamName', CASE pro.task_type_enum WHEN 2 THEN art.serial_number WHEN 16 THEN ass.serial_number END serialNumber, sum(pro.quantity) totalQuantity FROM mes_building_produce_team_report pro LEFT JOIN mes_building_task task ON pro.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN contract_project cp ON task.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN mes_building_process pss ON pro.process_id = pss.id AND pss.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON pro.product_id = art.id AND art.bool_delete_enum = 0 AND pro.task_type_enum = 2 LEFT JOIN tech_assemble ass ON pro.product_id = ass.id AND ass.bool_delete_enum = 0 AND pro.task_type_enum = 16 LEFT JOIN mes_building_team_user_link tulink ON pro.team_id = tulink.team_id AND tulink.bool_delete_enum = 0 AND tulink.bool_leader_enum = 1 where pro.bool_delete_enum = 0 and pro.quantity > pro.inspection_quantity
and task.workshop_id = #{workShopId}
and task.production_line_id = #{productionId}
GROUP BY cp.`name`, pss.`name`, pro.task_type_enum, tulink.team_id, tulink.user_name, serialNumber

SELECT cp.serial_number as serialCode, cp.short_name as shortName, pss.NAME as processName, ul.NAME as inspectUserName, CASE pro.task_type_enum WHEN 2 THEN art.serial_number WHEN 16 THEN ass.serial_number END serial_number FROM mes_building_produce_team_report pro LEFT JOIN mes_building_task task ON pro.task_id = task.id AND task.bool_delete_enum = 0 LEFT JOIN contract_project cp ON task.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN mes_building_process pss ON pro.process_id = pss.id AND pss.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON pro.product_id = art.id AND art.bool_delete_enum = 0 AND pro.task_type_enum = 2 LEFT JOIN tech_assemble ass ON pro.product_id = ass.id AND ass.bool_delete_enum = 0 AND pro.task_type_enum = 16 LEFT JOIN mes_inspect_config inspect_config ON inspect_config.workshop_id = task.workshop_id AND inspect_config.bool_delete_enum = 0 LEFT JOIN mes_inspect_config_user_link culink ON culink.inspect_config_id = inspect_config.id AND culink.bool_delete_enum = 0 LEFT JOIN sys_user ul ON culink.inspect_user_id = ul.id AND ul.bool_delete_enum = 0 WHERE pro.bool_delete_enum = 0 AND inspect_config.STATUS = 1 AND pro.quantity > pro.inspection_quantity and pro.id in
#{id}
GROUP BY cp.serial_number, cp.short_name, pss.NAME, ul.NAME, serial_number;

SELECT artifact.name, artifact.structure_class_id, sum(report.quantity) AS totalQuantity
,sum(report.quantity * artifact.net_weight) / 1000 AS totalMete
,sum(report.quantity * artifact.gross_weight) / 1000 AS totalMete
FROM mes_building_produce_team_report report LEFT JOIN tech_artifact artifact on artifact.id = report.product_id LEFT JOIN mes_building_production_line line on report.production_line_id = line.id where report.bool_delete_enum = 0 and report.task_type_enum = 2 and report.process_id = #{processId}
and artifact.project_id = #{projectId}
and artifact.monomer_id = #{monomerId}
and report.team_id = #{teamId}
and report.production_line_id in
#{item}
AND report.in_year_month_day_date = date_format(#{dateTime}, '%Y-%m-%d')
group by artifact.structure_class_id,artifact.name

SELECT DISTINCT report.id, workshop.name AS workshopName, line.name AS productionLineName, project.`name` AS projectName, project.`serial_number` AS projectSerialNumber, monomer.name As monomerName, area.name As areaName, batch.name As areaBatchName, teamLink.user_name AS teamUserName, buildingProcess .name AS processName, product.serial_number AS serialNumber, product.quantity As quantity, report.quantity AS reportQuantity, report.inspection_quantity AS inspectionQuantity, report.problem_quantity AS problemQuantity, report.number AS number, DATE_FORMAT(report.report_time, '%Y-%m-%d %H:%i') AS reportTime FROM mes_building_produce_team_report report LEFT JOIN mes_building_process buildingProcess on buildingProcess .id = report.process_id and buildingProcess.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line on line.id = report.production_line_id and line .bool_delete_enum = 0 LEFT JOIN mes_building_workshop workshop on workshop.id = line .workshop_id and workshop.bool_delete_enum = 0
LEFT JOIN tech_artifact product on report.product_id = product.id and product.bool_delete_enum = 0
LEFT JOIN tech_assemble product on report.product_id = product.id and product.bool_delete_enum = 0
LEFT JOIN contract_project project on project.id = product.project_id LEFT JOIN plan_monomer monomer on monomer.id = product.monomer_id LEFT JOIN plan_area area on area.id = product.area_id LEFT JOIN plan_area_batch batch on batch.id = product.area_batch_id LEFT JOIN mes_building_team team on report.team_id = team.id LEFT JOIN mes_building_team_user_link teamLink on team.id = teamLink.team_id and teamLink.bool_leader_enum = 1 and teamLink .bool_delete_enum = 0 where report.bool_delete_enum = 0 and report.task_type_enum = #{productType}
and report.project_id = #{projectId}
and report.monomer_id = #{monomerId}
and report.area_id = #{areaId}
and product.area_batch_id = #{areaBatchId}
and report.workshop_id = #{workshopId}
and report.production_line_id = #{productionLineId}
and report.team_id = #{teamId}
and report.process_id = #{processId}
AND product.serial_number like CONCAT('%', #{serialNumber},'%')
AND report.in_year_month_day_date >= date_format(#{dateTimeList[0]}, '%Y-%m-%d')
AND report.in_year_month_day_date <= date_format(#{dateTimeList[1]}, '%Y-%m-%d')

SELECT cp.id as 'projectInfo.id', cp.name as 'projectInfo.name', cp.serial_number as 'projectInfo.serialNumber', cp.short_name as 'projectInfo.shortName', sum(complete.quantity * artifact.net_weight) as mete, ROUND(sum(complete.quantity * artifact.net_weight) * 100 / ( SELECT sum(complete.quantity * artifact.net_weight) FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id and artifact.bool_delete_enum = 0 LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE complete.task_type_enum = 2 and complete.bool_delete_enum = 0
AND DATE_FORMAT(complete.create_time, "%Y-%m") = DATE_FORMAT(#{dateTime}, "%Y-%m")
AND DATE_FORMAT(complete.create_time, "%Y-%m-%d") = DATE_FORMAT(#{dateTime}, "%Y-%m-%d")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = cp.id )
AND complete.workshop_id = #{workshopId}
AND complete.project_id in
#{projectId}
),2) as ratio FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id and artifact.bool_delete_enum = 0 LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE complete.task_type_enum = 2 and complete.bool_delete_enum = 0
AND DATE_FORMAT(complete.create_time, "%Y-%m") = DATE_FORMAT(#{dateTime}, "%Y-%m")
AND DATE_FORMAT(complete.create_time, "%Y-%m-%d") = DATE_FORMAT(#{dateTime}, "%Y-%m-%d")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = cp.id )
AND complete.workshop_id = #{workshopId}
AND complete.project_id in
#{projectId}
group by cp.id

SELECT shop.id 'workshop.id', shop.name 'workshop.name', prss.id 'process.id', prss.name 'process.name', tulink.team_id 'team.id', tulink.user_name 'team.name', rep.task_type_enum,
CASE rep.task_type_enum when 1 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y') = DATE_FORMAT(#{dateTime}, "%Y") THEN part.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) when 2 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y') = DATE_FORMAT(#{dateTime}, "%Y") THEN art.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) when 16 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y') = DATE_FORMAT(#{dateTime}, "%Y") THEN ass.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) end as totalWeight,
CASE rep.task_type_enum when 1 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y-%m') = DATE_FORMAT(NOW(), '%Y-%m') THEN part.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) when 2 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y-%m') = DATE_FORMAT(NOW(), '%Y-%m') THEN art.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) when 16 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y-%m') = DATE_FORMAT(NOW(), '%Y-%m') THEN ass.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) end as currentTotalWeight,
CASE rep.task_type_enum when 1 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y-%m') = DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 MONTH),'%Y-%m') THEN part.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) when 2 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y-%m') = DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 MONTH),'%Y-%m') THEN art.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) when 16 then SUM(CASE WHEN DATE_FORMAT(rep.create_time, '%Y-%m') = DATE_FORMAT(DATE_SUB(NOW(), INTERVAL 1 MONTH),'%Y-%m') THEN ass.net_weight * COALESCE(rep.inspection_quantity, 0) ELSE 0 END) end as lastTotalWeight FROM mes_building_produce_team_report rep INNER JOIN mes_building_team_user_link tulink ON rep.team_id = tulink.team_id AND tulink.bool_leader_enum = 1 AND tulink.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line on rep.production_line_id = line.id AND line.bool_delete_enum = 0 LEFT JOIN mes_building_workshop shop on line.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN mes_building_process prss on rep.process_id = prss.id AND prss.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON rep.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN tech_assemble ass on rep.product_id = ass.id AND ass.bool_delete_enum = 0 LEFT JOIN tech_machine_part part ON part.id = rep.product_id and part.bool_delete_enum = 0 LEFT JOIN mes_building_task task ON task.id = rep.task_id and task.bool_delete_enum = 0 WHERE rep.bool_delete_enum = FALSE and rep.inspection_quantity != 0
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = task.project_id )
AND task.project_id in
#{projectId}
AND line.workshop_id = #{workshopId}
AND rep.process_id = #{processId}
GROUP BY shop.id, prss.id, tulink.team_id, tulink.user_name, rep.task_type_enum

SELECT cp.id AS 'projectInfo.id', cp.`name` AS 'projectInfo.name', cp.short_name AS 'projectInfo.short_name', cp.serial_number AS 'projectInfo.serial_number', IFNULL(a.taskMete,0) AS taskMete, IFNULL(b.mete,0) AS mete, CASE WHEN a.taskMete IS NULL THEN 0 WHEN b.mete IS NULL THEN 0 ELSE ROUND(b.mete * 100 / a.taskMete, 2) END AS ratio FROM contract_project as cp LEFT join (SELECT task.project_id, sum( task.task_quantity * artifact.net_weight ) AS taskMete FROM mes_building_task task LEFT JOIN tech_artifact artifact ON artifact.id = task.product_id AND artifact.bool_delete_enum = 0 WHERE task.task_type_enum = 2 and task.bool_delete_enum = 0
AND DATE_FORMAT(task.create_time, "%Y-%m" ) = DATE_FORMAT(#{yearMonth}, "%Y-%m")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = task.project_id )
AND task.workshop_id = #{workshopId}
AND task.project_id in
#{projectId}
group by task.project_id )a on a.project_id = cp.id LEFT JOIN ( SELECT complete.project_id, sum(complete.quantity * artifact.net_weight) as mete FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id and artifact.bool_delete_enum = 0 LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE complete.task_type_enum = 2 and complete.bool_delete_enum = 0
AND DATE_FORMAT(complete.create_time, "%Y-%m" ) = DATE_FORMAT(#{yearMonth}, "%Y-%m")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = complete.project_id )
AND complete.workshop_id = #{workshopId}
AND complete.project_id in
#{projectId}
group by complete.project_id )b ON b.project_id = cp.id where a.taskMete is not null or b.mete is not null

SELECT a.dateTime, a.taskMete, b.mete, ROUND(b.mete * 100 / a.taskMete,2) as ratio FROM ( SELECT DATE_FORMAT(task.create_time, "%Y-%m") as dateTime, sum(task.task_quantity * artifact.net_weight) as taskMete FROM mes_building_task task LEFT JOIN tech_artifact artifact ON artifact.id = task.product_id and artifact.bool_delete_enum = 0 LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE task.task_type_enum = 2 and task.bool_delete_enum = 0
AND DATE_FORMAT(task.create_time, "%Y" ) = DATE_FORMAT(#{year}, "%Y")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = cp.id )
AND task.workshop_id = #{workshopId}
AND task.project_id in
#{projectId}
group by DATE_FORMAT(task.create_time, "%Y-%m") )a LEFT JOIN ( SELECT DATE_FORMAT(complete.create_time, "%Y-%m") as dateTime, sum(complete.quantity * artifact.net_weight) as mete FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id and artifact.bool_delete_enum = 0 LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE complete.task_type_enum = 2 and complete.bool_delete_enum = 0
AND DATE_FORMAT(complete.create_time, "%Y" ) = DATE_FORMAT(#{year}, "%Y")
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = cp.id )
AND complete.workshop_id = #{workshopId}
AND complete.project_id in
#{projectId}
group by DATE_FORMAT(complete.create_time, "%Y-%m") )b on b.dateTime = a.dateTime

SELECT y_t.`year` as `dateTime`, IFNULL(temp1.mete,0) as `mete` FROM (
select DATE_FORMAT(#{i}, '%Y') as `year`
) y_t LEFT JOIN ( SELECT DATE_FORMAT(complete.create_time, "%Y" ) as dateTime, sum(complete.quantity * artifact.net_weight) as mete FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id and artifact.bool_delete_enum = 0 LEFT JOIN contract_project as cp on cp.id = artifact.project_id and cp.bool_delete_enum = FALSE WHERE complete.task_type_enum = 2 and complete.bool_delete_enum = 0
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = cp.id )
AND complete.workshop_id = #{workshopId}
group by DATE_FORMAT(complete.create_time, "%Y" ) ) AS temp1 ON temp1.dateTime = y_t.`year`

SELECT shop.`name` shopName, line.`name` lineName, IFNULL(sum(tp.task_quantity * art.net_weight )/1000,0) currentMonthScheduling FROM mes_building_task_process pro left join mes_building_task tp on pro.task_id = tp.id and tp.bool_delete_enum = 0 Inner JOIN tech_artifact art ON pro.product_id = art.id AND art.bool_delete_enum = 0 and pro.task_type_enum = 2 LEFT JOIN mes_building_workshop shop ON pro.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN mes_building_production_line line ON pro.production_line_id = line.id and line.product_type = 2 AND line.bool_delete_enum = 0 WHERE pro.bool_delete_enum = 0 AND pro.need_quantity - pro.complete_quantity > 0
and pro.workshop_id = #{workshopId}
and tp.create_time between #{monthStart} and #{monthEnd} GROUP BY shop.`name`, line.`name`
